action.mutation:
mutation CreateShiftGroup($payload: [ShiftGroupCreatePayloadInput!]!) {
  mutation: createShiftGroup(payload: $payload) { 
    id
    name
  }
}

mutation UpdateShiftGroup($payload: [ShiftGroupUpdatePayloadInput!]!) {
  mutation: updateShiftGroup(payload: $payload) { 
    id
    name
  }
}

mutation DeleteShiftGroup($payload: [ShiftGroupDeletePayloadInput!]!) {
  mutation: deleteShiftGroup(payload: $payload) { 
    id
    name
  }
}
